mapper.select:
SELECT * FROM ai_message WHERE conversation_id=#{conversationId} AND is_deleted=0
 AND sequence_no > #{cursor} 
ORDER BY sequence_no ASC LIMIT #{limit}

SELECT * FROM (
    SELECT * FROM ai_message WHERE conversation_id=#{conversationId} AND is_deleted=0
    ORDER BY sequence_no DESC LIMIT #{limit}
) recent ORDER BY sequence_no ASC

mapper.update:
UPDATE ai_message SET content=#{content}, status=#{status}, model_name=#{modelName},
    token_usage=#{tokenUsage}, latency_ms=#{latencyMs}, grounded=#{grounded}
WHERE id=#{id} AND role='assistant' AND is_deleted=0

